"""Capture source contracts; run deliberately when adopting a new baseline.

This reads shipped source/seed data, never legacy/local_data. It does not import
legacy modules, connect to a running TACTIC, or execute Handler procedures.
"""
import argparse
import ast
from contextlib import closing
import hashlib
import json
from pathlib import Path
import re
import sqlite3

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "src/tactic_stream/compatibility"


def journal_schema(legacy):
    seed = legacy / 'src/install/start/db/sthpw.db'
    names = ('transaction_log', 'transaction_state', 'sobject_log', 'retire_log')
    with closing(sqlite3.connect(seed.as_uri() + '?mode=ro', uri=True)) as db:
        db.row_factory = sqlite3.Row
        tables = {name: db.execute('SELECT sql FROM sqlite_master WHERE name=?', (name,)).fetchone()[0] for name in names}
        registry = [dict(row) for row in db.execute('SELECT * FROM search_object') if row['search_type'] in {'sthpw/' + name for name in names}]
        registry_sql = db.execute("SELECT sql FROM sqlite_master WHERE name='search_object'").fetchone()[0]
    schema = (legacy / 'src/pyasm/search/upgrade/sqlite/sthpw_schema.sql').read_text(encoding='utf-8')
    tables['change_timestamp'] = re.search(r'CREATE TABLE "change_timestamp" \(.*?\n\);', schema, re.S).group().rstrip(';')
    tree = ast.parse((legacy / 'src/pyasm/search/upgrade/project/sthpw_upgrade.py').read_text(encoding='utf-8'))
    methods = {node.name: node for node in ast.walk(tree) if isinstance(node, ast.FunctionDef)}
    def sql(method):
        return next(node.args[0].value.strip() for node in ast.walk(methods[method]) if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'run_sql')
    with closing(sqlite3.connect(':memory:')) as db:
        db.row_factory = sqlite3.Row
        db.execute(registry_sql)
        db.execute(sql('critical_v4_0_0_a01_000c'))
        registry.append(dict(db.execute('SELECT * FROM search_object').fetchone()))
    columns = []
    for method in ('upgrade_v4_0_0_a01_018', 'upgrade_v4_0_0_a01_019', 'upgrade_v4_0_0_a01_022',
                   'upgrade_v4_0_0_a01_006', 'upgrade_v4_0_0_rc02_002',
                   'upgrade_v4_5_0_a01_002', 'upgrade_v4_5_0_a01_003', 'upgrade_v4_5_0_a01_004',
                   'critical_v4_5_0_a01_006', 'upgrade_v4_6_0_a02_001'):
        statement = sql(method)
        match = re.match(r'ALTER TABLE "?(\w+)"? ADD (?:COLUMN )?"?(\w+)"?', statement)
        columns.append({'table': match[1], 'column': match[2], 'sql': statement, 'source_method': method})
    indexes = []
    for name in ('transaction_log_timestamp_idx', 'transaction_log_idx'):
        statement = re.search(r'CREATE INDEX "' + name + r'" .*?;', schema).group()
        indexes.append({'name': name, 'sql': statement})
    return {'tables': tables, 'registry': registry, 'columns': columns, 'indexes': indexes}


def pipeline_schema(legacy):
    seed = legacy / 'src/install/start/db/sthpw.db'
    with closing(sqlite3.connect(seed.as_uri() + '?mode=ro', uri=True)) as db:
        db.row_factory = sqlite3.Row
        table = db.execute("SELECT sql FROM sqlite_master WHERE name='pipeline'").fetchone()[0]
        registry = [dict(row) for row in db.execute("SELECT * FROM search_object WHERE search_type='sthpw/pipeline'")]
    tree = ast.parse((legacy / 'src/pyasm/search/upgrade/project/sthpw_upgrade.py').read_text(encoding='utf-8'))
    methods = {node.name: node for node in ast.walk(tree) if isinstance(node, ast.FunctionDef)}
    columns = []
    for method in ('upgrade_v4_4_0_a01_004', 'upgrade_v4_4_0_a01_006',
                   'upgrade_v4_6_0_a01_002', 'upgrade_v4_6_0_a02_002',
                   'upgrade_v4_6_0_a03_009', 'upgrade_v4_6_0_a03_010',
                   'upgrade_v4_6_0_a03_012', 'upgrade_v4_7_0_a08_001'):
        statement = next(node.args[0].value.strip() for node in ast.walk(methods[method])
                         if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
                         and node.func.attr == 'run_sql' and 'jsonb' not in node.args[0].value)
        match = re.match(r'ALTER TABLE "?(\w+)"? ADD (?:COLUMN )?"?(\w+)"?', statement)
        columns.append({'table': match[1], 'column': match[2], 'sql': statement, 'source_method': method})
    return {'tables': {'pipeline': table}, 'registry': registry, 'columns': columns}


