def snapshot_schema(legacy):
    seed = legacy / 'src/install/start/db/sthpw.db'
    with closing(sqlite3.connect(seed.as_uri() + '?mode=ro', uri=True)) as db:
        db.row_factory = sqlite3.Row
        names = ('snapshot', 'file')
        tables = {name: db.execute('SELECT sql FROM sqlite_master WHERE name=?', (name,)).fetchone()[0] for name in names}
        registry = [dict(row) for row in db.execute('SELECT * FROM search_object')
                    if row['search_type'] in {'sthpw/' + name for name in names}]
    tree = ast.parse((legacy / 'src/pyasm/search/upgrade/project/sthpw_upgrade.py').read_text(encoding='utf-8'))
    columns = []
    nullable = []
    for method in (node for node in ast.walk(tree) if isinstance(node, ast.FunctionDef)):
        for node in ast.walk(method):
            if not isinstance(node, ast.Call) or not node.args or not isinstance(node.args[0], ast.Constant):
                continue
            sql = node.args[0].value
            if not isinstance(sql, str):
                continue
            sql = sql.strip()
            drop = re.fullmatch(r'ALTER TABLE \"?(snapshot|file)\"? ALTER COLUMN \"?(\w+)\"? DROP NOT NULL;?', sql, re.I)
            if drop and not any(row['table'] == drop[1] and row['column'] == drop[2] for row in nullable):
                nullable.append({'table': drop[1], 'column': drop[2], 'source_method': method.name})
            match = re.fullmatch(r'ALTER TABLE "?(snapshot|file)"? ADD (?:COLUMN )?"?(data|server|search_code)"? .*?;?', sql, re.S | re.I)
            if not match:
                match = re.fullmatch(r'ALTER TABLE "?(search_object)"? ADD (?:COLUMN )?"?(metadata_parser)"? .*?;?', sql, re.S | re.I)
            if match and not any(row['table'] == match[1] and row['column'] == match[2] for row in columns):
                columns.append({'table': match[1], 'column': match[2], 'sql': sql, 'source_method': method.name})
    config = (legacy / 'src/pyasm/search/upgrade/sqlite/config_schema.sql').read_text(encoding='utf-8')
    schema = (legacy / 'src/pyasm/search/upgrade/sqlite/sthpw_schema.sql').read_text(encoding='utf-8')
    tables['spt_naming'] = re.search(r'CREATE TABLE "spt_naming" \(.*?\n\s*\);', config, re.S).group().rstrip(';')
    with closing(sqlite3.connect(seed.as_uri() + '?mode=ro', uri=True)) as db:
        registry_sql = db.execute("SELECT sql FROM sqlite_master WHERE name='search_object'").fetchone()[0]
    with closing(sqlite3.connect(':memory:')) as db:
        db.row_factory = sqlite3.Row
        db.execute(registry_sql)
        db.execute(next(line for line in schema.splitlines() if line.startswith('INSERT INTO "search_object"') and "'config/naming'" in line))
        registry.append(dict(db.execute('SELECT * FROM search_object').fetchone()))
    return {'tables': tables, 'registry': registry, 'columns': columns, 'nullable': nullable}


def workflow_schema(legacy):
    schema = (legacy / 'src/pyasm/search/upgrade/sqlite/sthpw_schema.sql').read_text(encoding='utf-8')
    config = (legacy / 'src/pyasm/search/upgrade/sqlite/config_schema.sql').read_text(encoding='utf-8')
    tables = {name: re.search(r'CREATE TABLE "' + name + r'" \(.*?\n\);', schema, re.S).group().rstrip(';')
              for name in ('message', 'message_log', 'subscription', 'interaction', 'wdg_settings', 'queue', 'exception_log', 'debug_log')}
    for name in ('spt_process_state', 'spt_process'):
        tables[name] = re.search(r'CREATE TABLE "' + name + r'" \(.*?\n\);', config, re.S).group().rstrip(';')
    seed = legacy / 'src/install/start/db/sthpw.db'
    with closing(sqlite3.connect(seed.as_uri() + '?mode=ro', uri=True)) as db:
        registry_sql = db.execute("SELECT sql FROM sqlite_master WHERE name='search_object'").fetchone()[0]
    with closing(sqlite3.connect(':memory:')) as db:
        db.row_factory = sqlite3.Row
        db.execute(registry_sql)
        for name in ('sthpw/message', 'sthpw/message_log', 'sthpw/subscription', 'sthpw/interaction', 'sthpw/wdg_settings', 'sthpw/queue', 'sthpw/exception_log', 'sthpw/debug_log', 'config/process_state', 'config/process'):
            statement = next(line for line in schema.splitlines() if line.startswith('INSERT INTO "search_object"') and "'" + name + "'" in line)
            db.execute(statement)
        registry = [dict(row) for row in db.execute('SELECT * FROM search_object')]
    tree = ast.parse((legacy / 'src/pyasm/search/upgrade/project/config_upgrade.py').read_text(encoding='utf-8'))
    columns = []
    for method_name, column in [('upgrade_v4_4_0_a01_002', 'workflow'), ('upgrade_v4_4_0_a01_003', 'subpipeline_code')]:
        method = next(n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef) and n.name == method_name)
        sql = next(n.args[0].value.strip() for n in ast.walk(method) if isinstance(n, ast.Call))
        columns.append({'table': 'spt_process', 'column': column, 'sql': sql, 'source_method': method_name})
    queue_tree = ast.parse((legacy / 'src/pyasm/search/upgrade/project/sthpw_upgrade.py').read_text(encoding='utf-8'))
    indexes = []
    for method in (node for node in ast.walk(queue_tree) if isinstance(node, ast.FunctionDef)):
        for node in ast.walk(method):
            if not isinstance(node, ast.Call) or not node.args or not isinstance(node.args[0], ast.Constant):
                continue
            statement = node.args[0].value
            if not isinstance(statement, str):
                continue
            match = re.fullmatch(r'\s*ALTER TABLE "?(queue|debug_log)"? ADD (?:COLUMN )?"?(\w+)"? .*?;?\s*', statement, re.S)
            if match:
                columns.append({'table': match[1], 'column': match[2], 'sql': statement.strip(), 'source_method': method.name})
            if re.match(r'\s*CREATE INDEX "queue_state_idx" ', statement):
                indexes.append({'name': 'queue_state_idx', 'sql': statement.strip()})
    return {'tables': tables, 'registry': registry, 'columns': columns, 'indexes': indexes}


def script_schema(legacy):
    schema = (legacy / 'src/pyasm/search/upgrade/sqlite/sthpw_schema.sql').read_text(encoding='utf-8')
    config = (legacy / 'src/pyasm/search/upgrade/sqlite/config_schema.sql').read_text(encoding='utf-8')
    seed = legacy / 'src/install/start/db/sthpw.db'
