def connection_schema(legacy):
    seed = legacy / 'src/install/start/db/sthpw.db'
    with closing(sqlite3.connect(seed.as_uri() + '?mode=ro', uri=True)) as db:
        db.row_factory = sqlite3.Row
        ddl = db.execute("SELECT sql FROM sqlite_master WHERE name='connection'").fetchone()[0]
        registry = [dict(row) for row in db.execute("SELECT * FROM search_object WHERE search_type='sthpw/connection'")]
    tree = ast.parse((legacy / 'src/pyasm/search/upgrade/project/sthpw_upgrade.py').read_text(encoding='utf8'))
    method = next(n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef) and n.name == 'upgrade_v4_4_0_a01_003')
    statement = next(n.args[0].value.strip() for n in ast.walk(method)
                     if isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute) and n.func.attr == 'run_sql')
    columns = [{'table': 'search_object', 'column': 'type', 'sql': statement, 'source_method': method.name}]
    method = next(n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef) and n.name == 'upgrade_v4_1_0_a01_009')
    statement = next(n.args[0].value.strip() for n in ast.walk(method)
                     if isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute) and n.func.attr == 'run_sql')
    columns.append({'table': 'search_object', 'column': 'default_layout', 'sql': statement, 'source_method': method.name})
    columns.append({'table': 'search_object', 'column': 'id_column',
                    'sql': 'ALTER TABLE search_object ADD COLUMN id_column varchar(256);',
                    'source_method': 'bootstrap_schema.sql'})
    return {'tables': {'connection': ddl}, 'registry': registry, 'columns': columns}


def plugin_schema(legacy):
    names = ('config/plugin', 'config/plugin_content', 'config/url')
